(()=>{
const words={
adminDailyNormal:['日常點檢批次填報正常','Batch daily normal entry','Registro diario normal por lote','Nhập hàng loạt kiểm tra bình thường'],
batchEntryHelp:['請先完成實際檢查，再選擇設備批次填報正常。已有同日同班紀錄（含草稿、異常及退回）的設備不會重填；未分配有效日常點檢表的設備會排除。送出後仍須主管簽核。','Complete actual inspections first. Existing records (including drafts, abnormal and rejected) and equipment without a valid daily form are excluded. Supervisor approval is still required.','Complete las inspecciones reales primero. Se excluyen registros existentes y equipos sin formulario diario válido. Se requiere aprobación del supervisor.','Kiểm tra thực tế trước. Loại trừ bản ghi đã có và thiết bị không có mẫu hợp lệ. Vẫn cần quản lý phê duyệt.'],
batchPreview:['預覽設備清單','Preview equipment','Vista previa de equipos','Xem trước thiết bị'],
batchActualCheck:['我確認勾選設備已實際完成全部點檢，所有項目均正常。','I confirm all selected equipment was actually inspected and every item is normal.','Confirmo que se inspeccionaron los equipos seleccionados y todos los ítems son normales.','Tôi xác nhận đã kiểm tra thực tế tất cả thiết bị đã chọn và mọi mục đều bình thường.'],
batchSubmit:['一鍵全數填報正常','Submit all selected as normal','Registrar seleccionados como normales','Gửi tất cả đã chọn là bình thường'],
batchSelectAll:['全選／取消全選','Select / deselect all','Seleccionar / deseleccionar todos','Chọn / bỏ chọn tất cả'],
batchReady:['可填報','Eligible','Disponibles','Có thể nhập'],
batchExisting:['已有紀錄，已排除','Existing records excluded','Registros existentes excluidos','Đã loại bản ghi hiện có'],
batchNoForm:['無有效點檢表，已排除','No valid form; excluded','Sin formulario válido; excluidos','Không có mẫu hợp lệ; đã loại'],
batchDone:['已成功填報','Successfully submitted','Registrados','Đã gửi thành công'],
batchSkipped:['未填報／已排除','Not submitted / skipped','No registrados / omitidos','Chưa gửi / bỏ qua'],
batchPending:['待完成／結果待確認','Pending / result uncertain','Pendientes / resultado incierto','Chờ hoàn tất / chưa rõ kết quả'],
batchRetry:['重試尚未完成的設備','Retry unfinished equipment','Reintentar equipos pendientes','Thử lại thiết bị chưa hoàn tất'],
batchFinish:['結束本批次並重新整理','Finish batch and refresh','Finalizar lote y actualizar','Kết thúc đợt và tải lại'],
batchInvalid:['請填寫點檢人、有效日期及班別；過去日期須填補登原因。','Enter inspector, valid date and shift. Past dates require a reason.','Introduzca inspector, fecha y turno. Fechas pasadas requieren motivo.','Nhập người kiểm tra, ngày và ca hợp lệ. Ngày trước cần lý do.'],
batchConfirmRequired:['請勾選設備並確認已完成實際檢查。','Select equipment and confirm actual inspection.','Seleccione equipos y confirme la inspección real.','Chọn thiết bị và xác nhận kiểm tra thực tế.'],
batchProgress:['填報進度','Submission progress','Progreso del registro','Tiến độ nhập'],
batchResume:['此批次保留原日期、班別與填報人；重試會使用相同識別碼，避免重複建立。','This batch retains its original date, shift and inspector. Retries reuse the same identifiers to prevent duplicates.','El lote conserva fecha, turno e inspector; los reintentos evitan duplicados.','Đợt giữ nguyên ngày, ca và người kiểm tra; thử lại không tạo bản ghi trùng.']
};for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
let optionsState={date:'',shift:'day',department:'',name:'',reason:''},preview=null,batch=null,busy=false;
const storageKey=()=>`inspection_normal_batch:${profile?.account_id}:${activeCountry}`;
function persist(){if(batch)sessionStorage.setItem(`inspection_normal_batch:${batch.account}:${batch.country}`,JSON.stringify(batch));else sessionStorage.removeItem(storageKey());}
function restore(){if(batch?.country===activeCountry&&batch?.account===profile?.account_id)return;batch=null;preview=null;try{const saved=JSON.parse(sessionStorage.getItem(storageKey())||'null');if(saved?.country===activeCountry&&saved?.account===profile?.account_id&&Array.isArray(saved.rows))batch=saved;}catch{}}
const previousRender=render;render=function(){if(view==='adminDailyNormal'&&profile?.role!=='admin')view='board';previousRender();if(profile?.role==='admin'&&activeCountry){const nav=document.createElement('button');nav.className='nav'+(view==='adminDailyNormal'?' active':'');nav.dataset.view='adminDailyNormal';nav.innerHTML=txt('adminDailyNormal');nav.onclick=()=>{view='adminDailyNormal';render();};$('.side').append(nav);}};
const previousContent=renderContent;renderContent=function(){if(view!=='adminDailyNormal')return previousContent();if(profile?.role!=='admin'||!activeCountry)return previousContent();restore();renderEntry();};
function renderEntry(){
 if(batch)return renderBatch();
 optionsState.date ||= inspectionDay();
 $('#content').innerHTML=`<div id="normalBatchAction"></div><p class="notice">${txt('batchEntryHelp')}</p><div class="editor-fields"><label>${txt('inspectionDate')}<input id="batchDate" class="select" type="date" max="${inspectionDay()}" value="${esc(optionsState.date)}"></label><label>${txt('shift')}<select id="batchShift" class="select">${['day','night'].map(s=>`<option value="${s}" ${optionsState.shift===s?'selected':''}>${txt(s)}</option>`).join('')}</select></label><label>${txt('department')}<select id="batchDepartment" class="select">${options(data.departments,optionsState.department,'all')}</select></label><label>${txt('inspector')}<input id="batchInspector" class="select" maxlength="100" value="${esc(optionsState.name)}"></label><label>${txt('backfillReason')}<textarea id="batchReason" maxlength="1000">${esc(optionsState.reason)}</textarea></label></div><p>${button('batchPreview','id="previewNormalBatch"','primary')}</p><p id="normalBatchError" role="alert"></p><div id="normalBatchPreview"></div>`;
 const fields={batchDate:'date',batchShift:'shift',batchDepartment:'department',batchInspector:'name',batchReason:'reason'};for(const[id,key]of Object.entries(fields))$('#'+id).oninput=e=>{optionsState[key]=e.target.value;preview=null;$('#normalBatchAction').replaceChildren();$('#normalBatchPreview').replaceChildren();};
 $('#previewNormalBatch').onclick=async()=>{if(busy)return;const o={...optionsState,name:optionsState.name.trim(),reason:optionsState.reason.trim()},today=inspectionDay();if(!o.name||!/^\d{4}-\d{2}-\d{2}$/.test(o.date)||!Number.isFinite(Date.parse(o.date))||new Date(o.date+'T00:00:00Z').toISOString().slice(0,10)!==o.date||o.date>today||o.date<today&&!o.reason){$('#normalBatchError').textContent=t('batchInvalid');return;}busy=true;const revision=JSON.stringify(optionsState),country=activeCountry,account=profile.account_id;$('#previewNormalBatch').disabled=true;try{const fresh=await api({action:'workspace'});if(view!=='adminDailyNormal'||country!==activeCountry||account!==profile?.account_id||revision!==JSON.stringify(optionsState))return;data=fresh;let existing=0,noForm=0;const candidates=[];for(const e of data.equipment.filter(e=>!e.archived_at&&e.status==='active'&&(!o.department||e.department_id===o.department))){if(data.records.some(r=>r.equipment_id===e.id&&recordDay(r)===o.date&&r.shift===o.shift)){existing++;continue;}const a=data.assignments.find(a=>a.equipment_id===e.id&&a.kind==='daily'),f=a&&data.forms.find(f=>f.id===a.form_id&&f.kind==='daily');if(!f?.updated_at||!Array.isArray(f.items)||!f.items.length||f.items.length>200){noForm++;continue;}candidates.push({equipment:e,form:f});}preview={options:o,country,account,candidates};$('#normalBatchPreview').innerHTML=`<p>${txt('inspectionDate')}：${esc(o.date)} · ${txt(o.shift)} · ${txt('inspector')}：${esc(o.name)}</p><p>${txt('batchReady')}：${candidates.length}；${txt('batchExisting')}：${existing}；${txt('batchNoForm')}：${noForm}</p><label class="checkbox-line"><input id="normalSelectAll" type="checkbox" checked>${txt('batchSelectAll')}</label>${table(['equipmentCode','equipmentName','item'],candidates.map((x,n)=>`<tr><td><label><input type="checkbox" data-normal-row="${n}" checked>${esc(x.equipment.equipment_code)}</label></td><td>${esc(nameOf(x.equipment))}</td><td><details><summary>${esc(x.form.form_name)} (${x.form.items.length})</summary><ol>${x.form.items.map(i=>`<li>${esc(multilingual(i.name))} — ${esc(multilingual(i.standard))}</li>`).join('')}</ol></details></td></tr>`).join(''))}<label class="checkbox-line"><input id="normalActualCheck" type="checkbox">${txt('batchActualCheck')}</label>`;$('#normalBatchAction').innerHTML=powerCheckButton('batchSubmit',`id="submitNormalBatch" ${candidates.length?'':'disabled'}`);$('#normalSelectAll').onchange=e=>{$$('[data-normal-row]').forEach(x=>x.checked=e.target.checked);$('#normalActualCheck').checked=false;};$$('[data-normal-row]').forEach(e=>e.onchange=()=>{$('#normalActualCheck').checked=false;$('#normalSelectAll').checked=$$('[data-normal-row]').every(x=>x.checked);});$('#submitNormalBatch').onclick=startBatch;}catch{if($('#normalBatchError'))$('#normalBatchError').textContent=t('error');}finally{busy=false;if($('#previewNormalBatch'))$('#previewNormalBatch').disabled=false;}};
}
async function startBatch(){if(busy||!preview||profile?.role!=='admin')return;const selected=$$('[data-normal-row]:checked').map(e=>preview.candidates[Number(e.dataset.normalRow)]);if(!selected.length||!$('#normalActualCheck').checked){$('#normalBatchError').textContent=t('batchConfirmRequired');return;}if(preview.country!==activeCountry||preview.account!==profile.account_id)return;const id=crypto.randomUUID(),o=preview.options;batch={id,country:activeCountry,account:profile.account_id,options:o,rows:selected.map(x=>({code:x.equipment.equipment_code,status:'pending',payload:{action:'admin_daily_normal',equipment_id:x.equipment.id,form_id:x.form.id,form_updated_at:x.form.updated_at,inspector_name:o.name,shift:o.shift,inspection_date:o.date,is_backfill:o.date<inspectionDay(),backfill_reason:o.reason,submission_key:crypto.randomUUID(),batch_id:id,confirmed:true}}))};try{persist();}catch{batch=null;$('#normalBatchError').textContent=t('error');return;}await runBatch();}
function renderBatch(){const counts={done:0,skipped:0,pending:0};batch.rows.forEach(r=>counts[r.status]++);$('#content').innerHTML=`<p class="notice">${txt('batchResume')}</p><p>${txt('inspectionDate')}：${esc(batch.options.date)} · ${txt(batch.options.shift)} · ${txt('inspector')}：${esc(batch.options.name)}</p><p id="normalBatchProgress" role="status">${txt('batchProgress')}：${counts.done+counts.skipped}/${batch.rows.length}；${txt('batchDone')}：${counts.done}；${txt('batchSkipped')}：${counts.skipped}；${txt('batchPending')}：${counts.pending}</p>${table(['equipmentCode','status'],batch.rows.map(r=>`<tr><td>${esc(r.code)}</td><td>${txt({done:'batchDone',skipped:'batchSkipped',pending:'batchPending'}[r.status])}${r.error?' · '+esc(r.error):''}</td></tr>`).join(''))}<p>${button('batchRetry',`id="retryNormalBatch" ${busy||!counts.pending?'disabled':''}`,'primary')} ${button('batchFinish',`id="finishNormalBatch" ${busy?'disabled':''}`)}</p>`;$('#retryNormalBatch').onclick=runBatch;$('#finishNormalBatch').onclick=async()=>{if(busy)return;batch=null;persist();preview=null;await load();};}
async function runBatch(){if(busy||!batch||profile?.role!=='admin'||batch.country!==activeCountry||batch.account!==profile.account_id)return;busy=true;countryBusy++;const current=batch;renderBatch();try{for(const row of current.rows){if(row.status!=='pending')continue;if(current.country!==activeCountry||current.account!==profile?.account_id)break;try{await api(row.payload);row.status='done';delete row.error;}catch(e){if(['existing_inspection','invalid_equipment','form_not_assigned','form_changed','invalid_record','invalid_batch_entry','invalid_inspection_date'].includes(e.message)){row.status='skipped';row.error=t(e.message==='existing_inspection'?'batchExisting':e.message==='form_changed'||e.message==='form_not_assigned'?'formChanged':'batchInvalid');}else{row.error=t('error');break;}}finally{persist();if(view==='adminDailyNormal'&&current.country===activeCountry)renderBatch();}}}finally{countryBusy--;busy=false;if(view==='adminDailyNormal'&&current.country===activeCountry&&current.account===profile?.account_id)renderBatch();}}
})();
